**********************	Export StripStrip	PROC	Export BusyECBusyEC	ldx #0	Export BusyErrBusyErr	jsl DecBusyFlg	bra ErrOut	Export EndCallEndCall	ldx #0	Export ErrOutErrOut	pld	; restore direct register	Export oErrOutoErrOut	jml >$e10184;	phy	; save amount to strip on stack;	tsc	; get stack pointer;	clc	; add to it the amount to strip;	adc 1,s;	tay	; put this result in Y;	tsc	; get back orig stack pointer;	phx	; save error on stack;	tax	; put orig stack in	X;	phb	; now save the data	bank reg;	pea $0000	; set data bank reg	to 0;	plb;	plb;	lda |3+4,x	; now use x and y to move 6 bytes;	sta |3+4,y	; of rtl info from current pos;	lda |3+2,x	; to final pos.;	sta |3+2,y;	lda |3+0,x;	sta |3+0,y;	plb	; restore data bank	register;	plx	; restore x register with error;;	tsc	; get stack again;	clc	; bump it by amount	to strip Plus 2;	adc 1,s	; to make up for amount to strip;	adc #2	; still on stack;	tcs	; reset stack pointer;	txa	; error into a-reg;	cmp #1	; set carry correctly;	rtl	; fini	Export oBusyECoBusyEC	ldx #0	Export oBusyErroBusyErr	jsl DecBusyFlg	bra oErrOut	Export oEndCalloEndCall	ldx #0	bra oErrOut	ENDP	END